import json,re
from pathlib import Path
data=json.loads(Path('/root/DATA/products/PersonalizeForce.json').read_text())
msgs=data['slack']
def all_texts():
    for m in msgs:
        yield m.get('Channel',{}).get('name'), m.get('Message',{}).get('User',{})
        for r in m.get('ThreadReplies') or []:
            yield m.get('Channel',{}).get('name'), r.get('User',{})
url_re=re.compile(r'https?://[^\s>]+')
demo_urls=set()
demo_msgs=[]
for ch,u in all_texts():
    txt=u.get('text','') or ''
    if 'demo' in txt.lower() and 'http' in txt.lower():
        for url in url_re.findall(txt):
            if 'demo' in url.lower():
                demo_urls.add(url.rstrip(').,!?'))
                demo_msgs.append((url,ch,u.get('userId'),txt))
print('unique demo urls',len(demo_urls))
for url in sorted(demo_urls):
    print(url)
print('\nSample demo-related messages:')
for url,ch,uid,txt in demo_msgs[:10]:
    print('\n',ch,uid,url,'\n ',txt)
