import json, re
from pathlib import Path
:def token_count(text: str) -> int:
    try:
        import tiktoken  # type: ignore
        enc = tiktoken.get_encoding('cl100k_base')
        return len(enc.encode(text))
    except Exception:
        # Fallback: rough approximation
        return max(1, len(re.findall(r"\S+", text)))
s# --- Load questions (non-strict JSON in question.txt) ---
q_text = Path('/root/question.txt').read_text()
q_pairs = re.findall(r'"(q\d+)"\s*:\s*(.*?)(?:,\s*\n|\n\s*\})', q_text, flags=re.S)
questions = {k: v.strip() for k, v in q_pairs}
n# --- Q1: CoachForce Market Research Report authors + key reviewers ---
coach = json.loads(Path('/root/DATA/products/CoachForce.json').read_text())
coach_docs = {d['id']: d for d in coach.get('documents', [])}
# pick the best version: latest_... if present, else final_..., else base
mr_ids = [i for i in coach_docs if 'cofoaix_market_research_report' in i]
anchor_id = None
for cand in ['latest_cofoaix_market_research_report', 'final_cofoaix_market_research_report', 'cofoaix_market_research_report']:
    if cand in coach_docs:
        anchor_id = cand
        break
if not anchor_id:
    raise RuntimeError('Could not locate CoachForce Market Research Report document')
author_id = coach_docs[anchor_id].get('author')
# key reviewers from meeting transcript participants (evidenced feedback)
reviewers = []
for mt in coach.get('meeting_transcripts', []):
    if (mt.get('document_type') == 'Market Research Report' and 'CoFoAIX' in (mt.get('transcript') or '')):
        reviewers = list(mt.get('participants') or [])
        break
q1_answer = []
if author_id:
    q1_answer.append(author_id)
for rid in reviewers:
    if rid and rid not in q1_answer:
        q1_answer.append(rid)
# --- Q2/Q3: PersonalizeForce competitor insights + demo URLs ---
pers = json.loads(Path('/root/DATA/products/PersonalizeForce.json').read_text())
msgs = pers.get('slack', [])
def iter_texts():
    for m in msgs:
        ch = (m.get('Channel') or {}).get('name')
        u = ((m.get('Message') or {}).get('User') or {})
        yield ch, u, m.get('id')
        for r in (m.get('ThreadReplies') or []):
            ru = (r.get('User') or {})
            yield ch, ru, r.get('utterranceID') or r.get('id')
competitors = ['personaai', 'smartsuggest', 'tailorai']
insight_terms = [
    'weakness','weaknesses','strength','strengths','feature','features','issue','issues',
    'struggle','struggles','limited','steep learning curve','privacy','accuracy','setup cost',
    'integration','segmentation','predictive','a/b testing','dashboard','multi-channel','language support'
]
exclude_phrases = ['demo available here', 'thanks for the insights', 'thank you for the insights']
insight_ids_in_order = []
seen_ids = set()
for ch, u, mid in iter_texts():
    txt = (u.get('text') or '')
    low = txt.lower()
    if any(c in low for c in competitors):
        if any(p in low for p in exclude_phrases):
            continue
        if any(t in low for t in insight_terms):
            uid = u.get('userId')
            if uid and uid != 'slack_admin_bot' and uid not in seen_ids:
                seen_ids.add(uid)
                insight_ids_in_order.append(uid)
# demo URLs shared for competitor products (external only)
url_re = re.compile(r'https?://[^\s>]+')
competitor_demo_urls = []
seen_urls = set()
for ch, u, mid in iter_texts():
    txt = (u.get('text') or '')
    low = txt.lower()
    if 'demo' not in low or 'http' not in low:
        continue
    for url in url_re.findall(txt):
        clean = url.rstrip(').,!?')
        if any(c in clean.lower() for c in competitors) and 'demo' in clean.lower():
            if 'sf-internal.slack.com' in clean.lower():
                continue
            if clean not in seen_urls:
                seen_urls.add(clean)
                competitor_demo_urls.append(clean)
q2_answer = insight_ids_in_order
q3_answer = competitor_demo_urls
answers = {}
for qk in sorted(questions.keys(), key=lambda x: int(x[1:])):
    if qk == 'q1':
        ans_list = q1_answer
    elif qk == 'q2':
        ans_list = q2_answer
    elif qk == 'q3':
        ans_list = q3_answer
    else:
        ans_list = []
    # tokens: approximate tokens for serialized answer payload
    tok = token_count(json.dumps(ans_list, ensure_ascii=False))
    answers[qk] = {'answer': list(ans_list), 'tokens': int(tok)}
out_path = Path('/root/answer.json')
out_path.write_text(json.dumps(answers, indent=2, ensure_ascii=False))
# --- completion gate: read-back + schema validation ---
loaded = json.loads(out_path.read_text())
assert out_path.exists(), 'output file missing'
assert isinstance(loaded, dict) and loaded, 'top-level must be a non-empty dict'
for k, v in loaded.items():
    assert isinstance(v, dict) and 'answer' in v and 'tokens' in v
    assert isinstance(v['answer'], list), f'{k}.answer must be a list'
    assert isinstance(v['tokens'], int), f'{k}.tokens must be an int'
print(out_path.read_text())
